frappe.ui.form.on("Timesheet", {
    refresh(frm) {
        apply_plot_mode(frm);
    },

    custom_plot(frm) {
        apply_plot_mode(frm);
    },
});

frappe.ui.form.on("Timesheet Detail", {
    time_logs_add(frm, cdt, cdn) {
        frappe.model.set_value(cdt, cdn, "custom_spending_code", frm.doc.custom_spending_code || null);
        frappe.model.set_value(cdt, cdn, "custom_plot", frm.doc.custom_plot || null);
        enforce_blank_times_if_plot(frm, cdt, cdn);
    },

    hours(frm, cdt, cdn) {
        enforce_blank_times_if_plot(frm, cdt, cdn);
    },

    from_time(frm, cdt, cdn) {
        enforce_blank_times_if_plot(frm, cdt, cdn);
    },

    to_time(frm, cdt, cdn) {
        enforce_blank_times_if_plot(frm, cdt, cdn);
    },
});

function apply_plot_mode(frm) {
    const has_plot = !!frm.doc.custom_plot;

    // hide timer actions
    if (has_plot) {
        frm.remove_custom_button(__("Start Timer"));
        frm.remove_custom_button(__("Resume Timer"));
    }

    // disable manual time editing in child rows
    if (frm.fields_dict?.time_logs?.grid) {
        frm.fields_dict.time_logs.grid.toggle_enable("from_time", !has_plot);
        frm.fields_dict.time_logs.grid.toggle_enable("to_time", !has_plot);
    }

    (frm.doc.time_logs || []).forEach((row) => {
        if (has_plot || row.custom_plot) {
            row.from_time = null;
            row.to_time = null;
        }
    });

    frm.refresh_field("time_logs");
}

function enforce_blank_times_if_plot(frm, cdt, cdn) {
    setTimeout(() => {
        const row = locals[cdt][cdn];
        if (!row) return;
        if (!(frm.doc.custom_plot || row.custom_plot)) return;

        row.from_time = null;
        row.to_time = null;
        frm.refresh_field("time_logs");
    }, 0);
}

