frappe.ui.form.on("Department Appraisal", {
  refresh: function (frm) {
    render_goal_template(frm);
  },
  department: function (frm) {
    render_goal_template(frm);
  },
});

function render_goal_template(frm) {
  if (!frm.doc.department) {
    frm.fields_dict.custom_scoring_references.$wrapper.html(
      "<p><i>Please select a department.</i></p>"
    );
    return;
  }

  frappe.call({
    method: "victoryfarmsdeveloper.victoryfarmsdeveloper.customization.department_appraisal.department_appraisal.get_rendered_scoring_references",
    args: {
      department: frm.doc.department,
      doc_name: frm.doc.name,
    },
    callback: function (r) {
      frm.fields_dict.custom_scoring_references.$wrapper.html(
        r.message || "<p><i>Unable to load template.</i></p>"
      );
    },
  });
}

frappe.ui.form.on('Department Appraisal', {
  multiplier_template: function(frm) {
    frappe.after_ajax(() => {
      frm.fields_dict['appraisal_multiplier'].grid.refresh();
      setTimeout(() => {
        frm.fields_dict['appraisal_multiplier'].grid.grid_rows.forEach(row => {
          if (!row.doc.score) {
            row.doc.score = "1";
          }
        });
        frm.refresh_field('appraisal_multiplier');
      }, 10);
    });
  }
});

frappe.ui.form.on('Stock Entry', {
        validate: function (frm) {
                if (!frm.doc.custom_total_qty && !frm.doc.custom_number_of_crates) {
                        frm.doc.custom_total_qty = 0;
                        frm.doc.custom_number_of_crates = 0;
                        cur_frm.refresh_field('custom_total_qty');
                        cur_frm.refresh_field('custom_number_of_crates');
                }

                let total_qty = 0;
                let number_of_crates = 0;

                frm.doc.items.forEach((entry) => {
                        if (entry.item_code != 'STO-ITEM-2025-02205') {
                                total_qty += entry.qty;
                                if (entry.vf_crate_no) {
                                        number_of_crates += 1;
                                }
                        } else {
                                number_of_crates = entry.qty;
                        }
                });

                frm.doc.custom_total_qty = total_qty;
                frm.doc.custom_number_of_crates = number_of_crates;
                cur_frm.refresh_field('custom_total_qty');
                cur_frm.refresh_field('custom_number_of_crates');
        }
});

frappe.ui.form.on('Employee', {
    department: function(frm) {
        if (frm.doc.department) {
            frappe.db.get_value('Department', frm.doc.department, 'payroll_cost_center', (r) => {
                if (r && r.payroll_cost_center) {
                    frm.set_value('payroll_cost_center', r.payroll_cost_center);
                } else {
                    frm.set_value('payroll_cost_center', null);
                }
            });
        } else {
            frm.set_value('payroll_cost_center', null);
        }
    },
    validate: function(frm) {
        if (frm.doc.department) {
            frappe.db.get_value('Department', frm.doc.department, 'payroll_cost_center', (r) => {
                if (r && r.payroll_cost_center && r.payroll_cost_center !== frm.doc.payroll_cost_center) {
                    frappe.msgprint(__('Payroll Cost Center does not match the Department\'s Payroll Cost Center.'));
                    frappe.validated = false;
                }
            });
        }
    }
});

frappe.listview_settings['Employee'] = {
    onload: function(listview) {
        listview.settings.add_fields = ['department'];

        listview.page.add_action_item(__('Update Payroll Cost Center'), function() {
            let selected_employees = listview.get_checked_items();

            if (selected_employees.length === 0) {
                frappe.msgprint(__('Please select at least one employee.'));
                return;
            }

            frappe.show_alert({
                message: __('Updating Payroll Cost Center for selected employees'),
                indicator: 'blue'
            });

            let updated_count = 0;
            let total_employees = selected_employees.length;

            function processEmployee(index) {
                if (index >= total_employees) {
                    frappe.msgprint({
                        title: __('Process Complete'),
                        message: `${updated_count} out of ${total_employees} employees updated successfully.`,
                        indicator: updated_count === total_employees ? 'green' : 'orange'
                    });
                    listview.refresh();
                    return;
                }

                let emp = selected_employees[index];

                frappe.db.get_value('Employee', emp.name, 'department', (r) => {
                    if (!r || !r.department) {
                        console.log(`Employee ${emp.name} has no department.`);
                        processEmployee(index + 1);
                        return;
                    }

                    frappe.db.get_value('Department', r.department, 'payroll_cost_center', (dept) => {
                        if (!dept || !dept.payroll_cost_center) {
                            console.log(`Department ${r.department} has no payroll cost center.`);
                            processEmployee(index + 1);
                            return;
                        }

                        frappe.db.set_value('Employee', emp.name, {
                            payroll_cost_center: dept.payroll_cost_center
                        }).then(() => {
                            updated_count++;
                            processEmployee(index + 1);
                        }).catch((err) => {
                            console.error(`Error updating ${emp.name}:`, err);
                            processEmployee(index + 1);
                        });
                    });
                });
            }

            processEmployee(0);
        });
        listview.page.add_action_item(__("Update Base Salary"), () => {
            const selected_values = listview.get_checked_items();
			frappe.call({
				method: "navari_vf.navari_vf.customizations.employee.utils.update_salary_details.update_salary_details",
				freeze: true,
				args: {
					selected_values: selected_values,
				},
				callback: function (r) {
					if (!r.exc) {
                        frappe.msgprint(__("Salary details updated for selected Employees"))
						listview.refresh();
					}
				},
			});
        })
    }
};

frappe.ui.form.on('Sales Invoice', {
    before_save: function(frm) {
        // Set the selling_price_list to "Victory Farms Loyalty Program"
        frm.set_value('selling_price_list', 'Victory Farms Loyalty Program');

        // Check if redeem_loyalty_points is checked and doc status is Draft
        if (frm.doc.redeem_loyalty_points && frm.doc.docstatus === 0) {
            let grand_total = frm.doc.grand_total;

            frm.doc.items = frm.doc.items.map(item => {

                // Calculate loyalty points based on loyalty item
                if (item.item_name === "Trolley Cooler Box") {
                    item.loyalty_points = grand_total / 1.14;
                } else if (item.item_name === "Apron Loyalty Program") {
                    item.loyalty_points = grand_total / 3.47;
                } else if (item.item_name === "Parasol") {
                    item.loyalty_points = grand_total / 5;
                } else if (item.item_name === "Large Frying Pan") {
                    item.loyalty_points = grand_total / 2.2;
                } else if (item.item_name === "Metallic Spoon - Ladle") {
                    item.loyalty_points = grand_total / 2.5;
                } else if (item.item_name === "Dust Coat") {
                    item.loyalty_points = grand_total / 4.07;
                } else {
                    item.loyalty_points = grand_total / 1; 
                }

                // Set income_account and expense_account directly
                // item.income_account = '600016 - Grant Loyalty Earned - VFL';
                // item.expense_account = '600015 - KES Grant Liability - VFL';
                // item.cost_center = '406001 - Commercial Management - VFL';

                return item;
            });

           // Refresh the items table to reflect changes
            frm.refresh_field('items');

            // Calculate and set the total loyalty points (rounded)
            const total_loyalty_points = frm.doc.items.reduce((sum, item) => sum + (item.loyalty_points || 0), 0);
            frm.set_value('loyalty_points', Math.round(total_loyalty_points));
            frm.set_value('paid_amount', grand_total);
            frm.set_value('loyalty_amount', grand_total);

            // Set correct debit_to account
            // frm.set_value('debit_to', '600016 - Grant Loyalty Earned - VFL');
        }
    }
});

