frappe.ui.form.on('Leave Application', {
    before_submit(frm) {
        // Block submission if status is "Pending Sufficient Balance"
        if (frm.doc.status === "Pending Sufficient Balance") {
            frappe.throw(__("You cannot submit a Leave Application while it is in Pending Sufficient Balance status."));
        }
    },

    validate(frm) {
        // Only check and set status for Annual Leave
        if (frm.doc.leave_type === "Annual Leave") {
            frappe.call({
                method: "hrms.hr.doctype.leave_application.leave_application.get_leave_balance_on",
                args: {
                    employee: frm.doc.employee,
                    leave_type: frm.doc.leave_type,
                    date: frm.doc.from_date
                },
                callback: function(r) {
                    const balance = r.message || 0;
                    const total_days = frm.doc.total_leave_days || 0;

                    if (balance < total_days) {
                        // Set status to pending if not already set
                        if (frm.doc.status !== "Pending Sufficient Balance") {
                            frm.set_value("status", "Pending Sufficient Balance");
                            frappe.msgprint({
                                title: __("Insufficient Leave Balance"),
                                message: __("Leave balance is insufficient. Status set to 'Pending Sufficient Balance'."),
                                indicator: "orange"
                            });
                        }
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Employee', {
    refresh(frm) {
        sync_custom_reasons(frm);
        apply_employee_mandatory_rules(frm);
        apply_employee_auto_populate(frm);
        load_bank_name_options(frm);
    },
    status(frm) { apply_employee_mandatory_rules(frm); },
    salary_currency(frm) { apply_employee_mandatory_rules(frm); },
    custom_transfer_type(frm) { apply_employee_mandatory_rules(frm); },
    residential_status(frm) { apply_employee_mandatory_rules(frm); },
    relieving_date(frm) { apply_employee_mandatory_rules(frm); },
    reason_for_leaving(frm) { apply_employee_mandatory_rules(frm); },
    custom_reasons(frm) { sync_custom_reasons(frm); },
    leave_encashed(frm) { apply_employee_mandatory_rules(frm); },
    employee_number(frm) { apply_employee_auto_populate(frm); },
    validate(frm) {
        sync_custom_reasons(frm);
        apply_employee_auto_populate(frm);
        apply_employee_mandatory_rules(frm);
    }
});

function sync_custom_reasons(frm) {
    if (frm.doc.custom_reasons && frm.fields_dict['reason_for_leaving']) {
        frm.set_value('reason_for_leaving', frm.doc.custom_reasons);
    }
}

function apply_employee_mandatory_rules(frm) {
    const is_left = (frm.doc.status || '').toLowerCase() === 'left';
    const is_usd = frm.doc.salary_currency === 'USD';
    const transfer_type = frm.doc.custom_transfer_type || frm.doc.transfer_type;
    const is_intl = transfer_type === 'International';
    const residential_status = frm.doc.residential_status || '';
    const is_resident = residential_status.toLowerCase().startsWith('resident');
    const has_relieving = !!frm.doc.relieving_date;
    const reason_for_leaving = frm.doc.reason_for_leaving || '';
    const is_resignation = reason_for_leaving.toLowerCase() === 'resignation';

    [
        'gender','date_of_birth','date_of_joining','status','department','employment_type',
        'designation','custom_job_title','reports_to','grade','custom_location',
        'custom_terms_of_service','contract_start_date','cell_number','personal_email',
        'person_to_be_contacted','emergency_phone_number','relation','attendance_device_id',
        'holiday_list','leave_approver','ctc','salary_currency','salary_mode',
        'custom_appraisal_template','bonus_potential','bank_name','custom_bank_code',
        'bank_branch_name','custom_branch_code','bank_ac_no','custom_validation_id',
        'national_id','nssf_no','shif_no','tax_id','residential_status',
        'type_of_employee','type_of_housing'
    ].forEach(f => _set_reqd(frm, f, 1));

    _set_reqd(frm, 'default_shift', 0);

    _set_reqd(frm, 'relieving_date', is_left ? 1 : 0);
    _set_first_reqd(frm, ['custom_account_name'], is_usd ? 1 : 0);
    _set_first_reqd(frm, ['tax_id'], is_resident ? 1 : 0);
    _set_first_reqd(frm, ['shif_no'], is_resident ? 1 : 0);
    _set_reqd(frm, 'custom_reasons', has_relieving ? 1 : 0);
    _set_reqd(frm, 'leave_encashed', has_relieving ? 1 : 0);

    const is_encashed = ['Yes', 1, true].includes(frm.doc.leave_encashed);
    _set_reqd(frm, 'encashment_date', (has_relieving && is_encashed) ? 1 : 0);
    _set_reqd(frm, 'resignation_letter_date', is_resignation ? 1 : 0);

    const bank_not_required = is_usd && is_intl;
    _set_reqd(frm, 'bank_name', bank_not_required ? 0 : 1);
    _set_reqd(frm, 'custom_bank_code', bank_not_required ? 0 : 1);
    _set_reqd(frm, 'bank_branch_name', bank_not_required ? 0 : 1);
    _set_reqd(frm, 'custom_branch_code', bank_not_required ? 0 : 1);
}

function apply_employee_auto_populate(frm) {
    const employee_value = frm.doc.employee_number || frm.doc.name;
    if (!frm.doc.attendance_device_id && employee_value && !employee_value.startsWith('new-employee')) {
        frm.set_value('attendance_device_id', employee_value);
    }
}

function load_bank_name_options(frm) {
    if (!frm.fields_dict['bank_name']) return;
    frappe.db.get_list('Bank', { fields: ['name'], limit: 0 }).then((banks) => {
        const options = banks.map(b => b.name).join('\n');
        frm.set_df_property('bank_name', 'options', options);
    });
}

function _find_first_field(frm, fields) {
    return fields.find(fieldname => frm.fields_dict[fieldname]);
}

function _set_first_reqd(frm, fields, val) {
    const fieldname = _find_first_field(frm, fields);
    if (fieldname) {
        frm.set_df_property(fieldname, 'reqd', val);
    }
}

function _set_reqd(frm, fieldname, val) {
    if (frm.fields_dict[fieldname]) {
        frm.set_df_property(fieldname, 'reqd', val);
    }
}

frappe.ui.form.on('Stock Entry', {
    refresh(frm) {
        if (frm.doc.stock_entry_type === 'Material Issue' && !frm.is_new()) {
            show_material_issue_workflow_status(frm);
        }
    },

    stock_entry_type(frm) {
        if (frm.doc.stock_entry_type === 'Material Issue' && frm.is_new()) {
            frappe.show_alert({
                message: __('Material Issue entries are governed by the Stock Transfer workflow and require approval before submission.'),
                indicator: 'blue'
            }, 5);
        }
    },

    before_submit(frm) {
        if (frm.doc.stock_entry_type === 'Material Issue') {
            const state = frm.doc.workflow_state || 'Draft';
            if (!['Approved', 'Submitted'].includes(state)) {
                frappe.throw(__('Material Issue entries must be approved before submission. Current status: {0}', [state]));
            }
        }
    }
});

function show_material_issue_workflow_status(frm) {
    const state = frm.doc.workflow_state || 'Draft';
    const colours = {
        'Draft': 'blue',
        'Pending Approval (Material Issue)': 'orange',
        'Pending Approval': 'orange',
        'Approved': 'green',
        'Submitted': 'green',
        'Rejected': 'red',
        'Cancelled': 'red'
    };
    frm.dashboard.add_comment(
        __('Material Issue workflow status: {0}', [state]),
        colours[state] || 'blue',
        true
    );
}

frappe.ui.form.on('Purchase Receipt', {
    refresh(frm) { apply_vf_purchase_receipt_rules(frm); },
    custom_type(frm) { apply_vf_purchase_receipt_rules(frm); },
    validate(frm) { apply_vf_purchase_receipt_rules(frm); }
});

function apply_vf_purchase_receipt_rules(frm) {
    // Landed Costs is never mandatory, for any Type.
    ['custom_landed_costs', 'landed_cost_voucher'].forEach(function (fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, 'reqd', 0);
            frm.refresh_field(fieldname);
        }
    });

    // Purchase Taxes and Charges Template is mandatory only for Feeds.
    // Matched with includes('feed') so both 'Feed' and 'Feeds' work.
    if (!frm.fields_dict.taxes_and_charges) {
        return;
    }

    const is_feeds = (frm.doc.custom_type || '').toLowerCase().indexOf('feed') !== -1;
    frm.set_df_property('taxes_and_charges', 'reqd', is_feeds ? 1 : 0);
    frm.set_df_property('taxes_and_charges', 'hidden', 0);
    frm.refresh_field('taxes_and_charges');
}

frappe.ui.form.on('Salary Slip', {
    refresh(frm) {
        show_note_column(frm, 'earnings');
        show_note_column(frm, 'deductions');
    }
});

function show_note_column(frm, table_field) {
    const grid = frm.fields_dict[table_field] && frm.fields_dict[table_field].grid;
    if (!grid) return;

    // Ensure custom_note is visible as a column in the child table
    grid.set_column_in_list_view('custom_note', true);
}

frappe.ui.form.on('Bulk Upload', {
    refresh(frm) {
        load_upload_type_options(frm);
    }
});

function load_upload_type_options(frm) {
    frappe.call({
        method: 'victoryfarmsdeveloper.victoryfarmsdeveloper.customization.payment_entry.payment_entry.get_upload_type_options',
        callback: function(r) {
            if (r.message) {
                frm.set_df_property('type', 'options', '\n' + r.message);
            }
        }
    });
}

frappe.ui.form.on('Expense Claim', {
    refresh(frm) {
        if (frm.is_new() && !frm.doc.expense_approver) {
            set_designated_approver(frm);
        }

        fetch_employee_currency(frm);
        configure_grid_columns(frm);
        apply_sub_type_rules_to_all_rows(frm);
        show_claim_status(frm);
    },

    employee(frm) {
        fetch_employee_currency(frm);
    },

    expenses_add(frm, cdt, cdn) {
        toggle_sub_type_for_row(frm, cdt, cdn, false);
    }
});

frappe.ui.form.on('Expense Claim Detail', {
    expense_claim_type(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        const is_dev = row.expense_claim_type === 'Development Allowance';

        toggle_sub_type_for_row(frm, cdt, cdn, is_dev);

        if (!is_dev) {
            frappe.model.set_value(cdt, cdn, 'custom_expense_sub_type', '');
        }

        sync_taxable_flag(frm);
    },

    custom_expense_sub_type(frm, cdt, cdn) {
        sync_taxable_flag(frm);
    }
});

function set_designated_approver(frm) {
    frappe.call({
        method: 'victoryfarmsdeveloper.victoryfarmsdeveloper.customization.expense_claim.expense_claim.get_designated_approver',
        callback(r) {
            if (r.message) {
                frm.set_value('expense_approver', r.message);
            }
        }
    });
}

function toggle_sub_type_for_row(frm, cdt, cdn, is_dev) {
    const grid = frm.fields_dict.expenses && frm.fields_dict.expenses.grid;
    if (!grid) return;

    const grid_row = grid.grid_rows_by_docname[cdn];
    if (!grid_row) return;

    if (grid_row.toggle_editable) {
        grid_row.toggle_editable('custom_expense_sub_type', is_dev);
    }

    if (grid_row.grid_form && grid_row.grid_form.fields_dict.custom_expense_sub_type) {
        const field = grid_row.grid_form.fields_dict.custom_expense_sub_type;
        field.df.hidden = !is_dev;
        field.df.reqd = is_dev;
        field.refresh();
    }
}

function apply_sub_type_rules_to_all_rows(frm) {
    if (!frm.doc.expenses) return;
    frm.doc.expenses.forEach(function(row) {
        const is_dev = row.expense_claim_type === 'Development Allowance';
        toggle_sub_type_for_row(frm, row.doctype, row.name, is_dev);
    });
}

function configure_grid_columns(frm) {
    const grid = frm.fields_dict.expenses && frm.fields_dict.expenses.grid;
    if (!grid) return;

    const desc_df = grid.docfields.find(df => df.fieldname === 'description');
    if (desc_df) {
        desc_df.hidden = 1;
        desc_df.in_list_view = 0;
    }

    const sub_df = grid.docfields.find(df => df.fieldname === 'custom_expense_sub_type');
    if (sub_df) {
        sub_df.hidden = 0;
        sub_df.in_list_view = 1;
    }

    grid.make_headings();
    grid.refresh();
}

function fetch_employee_currency(frm) {
    if (!frm.doc.employee) return;

    frappe.call({
        method: 'frappe.client.get_value',
        args: {
            doctype: 'Employee',
            filters: { name: frm.doc.employee },
            fieldname: 'salary_currency'
        },
        callback(r) {
            if (r.message && r.message.salary_currency) {
                frm.set_value('currency', r.message.salary_currency);
                frm.refresh_field('expenses');
            }
        }
    });
}

function sync_taxable_flag(frm) {
    const is_any_taxable = (frm.doc.expenses || []).some(row =>
        row.expense_claim_type === 'Development Allowance' &&
        row.custom_expense_sub_type &&
        row.custom_expense_sub_type.includes('(Taxable)')
    );
    frm.set_value('custom_is_taxable', is_any_taxable ? 1 : 0);
}

function show_claim_status(frm) {
    if (frm.doc.workflow_state) {
        const colors = {
            'Draft': 'blue',
            'Submitted': 'orange',
            'Approved': 'green',
            'Rejected': 'red'
        };
        frm.dashboard.add_comment(
            __('Status: {0}', [frm.doc.workflow_state]),
            colors[frm.doc.workflow_state] || 'blue',
            true
        );
    }
}
